34	 */
35	export const useContentfulClient = ({
36	  preview = false,
37	}: UseContentfulClientOptions = {}): UseContentfulClientResult => {
38	  const { spaceId, environment, previewAccessToken, accessToken } = getContentfulConfig() ?? {};
39	  const previewUnavailable = preview && !previewAccessToken;
40	  const isPreview = preview && !!previewAccessToken;
41	  const token = isPreview ? previewAccessToken : accessToken;
